// RomanToInt converts a valid uppercase Roman numeral to its integer value.
func RomanToInt(s string) int {
    r := map[rune]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total := 0
    for i := 0; i < len(s); i++ {
        if i+1 < len(s) && r[rune(s[i])] < r[rune(s[i+1])] {
            total -= r[rune(s[i])]
        } else {
            total += r[rune(s[i])]
        }
    }
    return total
}

