func Caesar(s string, n int) string {
	n = ((n%26)+26)%26 // normalize to 0..25
	runes := []rune(s)
	for i, r := range runes {
		switch {
		case unicode.IsUpper(r):
			runes[i] = 'A' + (r-'A'+rune(n))%26
		case unicode.IsLower(r):
			runes[i] = 'a' + (r-'a'+rune(n))%26
		}
	}
	return string(runes)
}

