func TopK(s string, k int) []string {
	w := strings.Fields(s)
	count := make(map[string]int, len(w))
	for _, w := range w {
		count[w]++
	}

	type pair struct {
		word  string
		count int
	}
	p := make([]pair, 0, len(count))
	for w, c := range count {
		p = append(p, pair{w, c})
	}
	sort.Slice(p, func(i, j int) bool {
		if p[i].count != p[j].count {
			return p[i].count > p[j].count
		}
		return p[i].word < p[j].word
	})

	var result []string
	for _, p := range p {
		if k > 0 {
			result = append(result, p.word)
			k--
		}
	}
	return result
}

