type Ring struct {
	items []int
	head  int
	n     int
}

func NewRing(cap int) *Ring {
	return &Ring{items: make([]int, cap)}
}

func (r *Ring) Push(v int) {
	r.items[r.head] = v
	r.head = (r.head + 1) % len(r.items)
	if r.n < len(r.items) {
		r.n++
	}
}

func (r *Ring) Items() []int {
	if r.n == 0 {
		return nil
	}
	out := make([]int, r.n)
	for i := 0; i < r.n; i++ {
		out[i] = r.items[(r.head+i)%len(r.items)]
	}
	return out
}

