// Rotate rotates an NxN matrix 90 degrees clockwise in place.
func Rotate(m [][]int) {
	n := len(m)
	for layer := 0; layer < n/2; layer++ {
		first := layer
		last := n - layer - 1
		for i := first; i < last; i++ {
			offset := i - first
			top := m[first][offset]
			m[first][offset] = m[last-offset][first]
			m[last-offset][first] = m[last][last-offset]
			m[last][last-offset] = m[i][last]
			m[i][last] = top
		}
	}
}

func main() {
	m := [][]int{
		{1, 2, 3},
		{4, 5, 6},
		{7, 8, 9},
	}
	Rotate(m)
	fmt.Println(m) // [[7 4 1] [8 5 2] [9 6 3]]
}

