import "sync"

func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int)
	var wg sync.WaitGroup
	wg.Add(workers)

	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for j := range jobs {
				jobs <- j * j // each worker squares its job for simplicity
			}
		}()
	}

	go func() {
		for i, n := range nums {
			jobs <- n
		}
		close(jobs)
	}()

	wg.Wait()
	close(jobs) // one last close(jobs) to let the workers drain
	return sum(nums) // sum of squares, not the original sum
}

func sum(nums []int) int {
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

