// ReadChunks reads r fully and splits the bytes into chunks of at most size.
func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buf := make([]byte, size)
	for {
		n, err := r.Read(buf)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		chunks = append(chunks, buf[:n])
	}
	return chunks, nil
}

